namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;
    private readonly List<Notification> _notifications = new()
    {
        new(1, "Welcome to the notification system!", DateTime.UtcNow.AddMinutes(-10)),
        new(2, "Your profile has been updated.", DateTime.UtcNow.AddMinutes(-5)),
        new(3, "New feature: Dark mode is now available.", DateTime.UtcNow.AddMinutes(-1)),
    };

    private readonly string[] _sampleMessages =
    {
        "Server maintenance scheduled for tonight.",
        "You have a new follower!",
        "Your report is ready to download.",
        "A comment was added to your post.",
        "Reminder: Team meeting in 30 minutes.",
        "System update completed successfully.",
        "New security alert for your account.",
    };

    /// <summary>
    /// Returns all current notifications.
    /// </summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>
    /// Returns only notifications newer than the given timestamp.
    /// </summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        // Simulate new notifications appearing randomly
        MaybeAddNotification();

        lock (_notifications)
        {
            var newer = _notifications.Where(n => n.Timestamp > since).ToList();
            return Task.FromResult(newer);
        }
    }

    private void MaybeAddNotification()
    {
        // ~40% chance of a new notification each poll
        if (Random.Shared.NextDouble() < 0.4)
        {
            var message = _sampleMessages[Random.Shared.Next(_sampleMessages.Length)];
            lock (_notifications)
            {
                _notifications.Add(new Notification(
                    _nextId++,
                    message,
                    DateTime.UtcNow));
            }
        }
    }
}

