@page "/notifications"
@using BlazorNotifications.Services
@implements IDisposable
@inject NotificationService NotificationSvc
@rendermode InteractiveServer

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p class="text-muted">No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var notification in _notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>
                    <span>@notification.Message</span>
                </div>
                <small class="text-muted">@notification.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@if (_isPolling)
{
    <p class="mt-3 text-success"><em>Live updates active — polling every 5 seconds</em></p>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private DateTime _lastCheck;

    /// <summary>
    /// Runs during SSR and again on interactive init.
    /// We only load data if the list is empty (i.e., first SSR call).
    /// On interactive re-init the data persists from prerender.
    /// </summary>
    protected override async Task OnInitializedAsync()
    {
        if (_notifications.Count == 0)
        {
            _notifications = await NotificationSvc.GetNotificationsAsync();
            _lastCheck = _notifications.Count > 0
                ? _notifications.Max(n => n.Timestamp)
                : DateTime.UtcNow;
        }
    }

    /// <summary>
    /// Called only once the component is truly interactive in the browser.
    /// This is where we start the polling loop — never during static SSR.
    /// </summary>
    protected override Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }

        return Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        _isPolling = true;
        await InvokeAsync(StateHasChanged);

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var newer = await NotificationSvc.GetNotificationsSinceAsync(_lastCheck);
                if (newer.Count > 0)
                {
                    _notifications.AddRange(newer);
                    _lastCheck = newer.Max(n => n.Timestamp);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }

        _isPolling = false;
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

